def largestIntegerWithDigitSum(n: int, s: int) -> str:
    if s < 0 or s > 9 * n:
        return ""
    if s == 0 and n > 1:
        return ""
    digits = []
    rem = s
    for _ in range(n):
        d = min(9, rem)
        digits.append(str(d))
        rem -= d
    return "".join(digits) if rem == 0 else ""

#include <string>
#include <algorithm>

class Solution {
public:
    std::string largestIntegerWithDigitSum(int n, int s) {
        if (s < 0 || s > 9 * n) return "";
        if (s == 0 && n > 1) return "";
        std::string res = "";
        int rem = s;
        for (int i = 0; i < n; ++i) {
            int d = std::min(9, rem);
            res += ('0' + d);
            rem -= d;
        }
        return rem == 0 ? res : "";
    }
};

class Solution {
    public String largestIntegerWithDigitSum(int n, int s) {
        if (s < 0 || s > 9 * n) return "";
        if (s == 0 && n > 1) return "";
        StringBuilder sb = new StringBuilder();
        int rem = s;
        for (int i = 0; i < n; i++) {
            int d = Math.min(9, rem);
            sb.append(d);
            rem -= d;
        }
        return rem == 0 ? sb.toString() : "";
    }
}

